import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ formData = {}, categories = [] }) {
  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSave = async () => {
    if (!categories.length) {
      alert("No categories selected for budgeting");
      return;
    }

    const payload = {
      incomeCategory: formData.incomeCategory || "",
      questionnaire: formData.questionnaire || {},
      spendingPriorities: formData.spendingPriorities || {},
      budgetLimits: limits
    };

    console.log("Sending to backend →", payload);

    try {
      const res = await fetch("http://localhost:5000/save-budget", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      const data = await res.json();

      if (res.ok && data.success) {
        alert("Data saved successfully ✅");
      } else {
        alert("Failed to save data");
      }
    } catch (error) {
      console.error("Server connection error:", error);
      alert("Server connection failed");
    }
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Set Monthly Budget Limits</h2>

        {categories.length === 0 ? (
          <p>No categories selected for budgeting</p>
        ) : (
          categories.map(category => (
            <div key={category} className="form-group">
              <label className="form-label">{category}</label>
              <input
                type="number"
                className="form-input"
                placeholder="Enter amount"
                onChange={e => handleChange(category, e.target.value)}
              />
            </div>
          ))
        )}

        <button className="next-button" onClick={handleSave}>
          Save Budget
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
